import{_ as n,o as t,c as i,a3 as a}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Mathematik, Text, Listen und Schleifen","description":"Vergleich der Blockly- und ioBroker-Blocks mit der nativen HA-Ausgabe von UGSo.","frontmatter":{"title":"Mathematik, Text, Listen und Schleifen","description":"Vergleich der Blockly- und ioBroker-Blocks mit der nativen HA-Ausgabe von UGSo."},"headers":[],"relativePath":"projects/blocks-for-ha/collections.md","filePath":"projects/blocks-for-ha/collections.md","lastUpdated":1792840662000}'),r={name:"projects/blocks-for-ha/collections.md"};function s(l,e,d,h,o,c){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="mathematik-text-listen-und-schleifen" tabindex="-1">Mathematik, Text, Listen und Schleifen <a class="header-anchor" href="#mathematik-text-listen-und-schleifen" aria-label="Permalink to &quot;Mathematik, Text, Listen und Schleifen&quot;">​</a></h1><p><strong>Seit 0.1.14:</strong> 37 zusätzliche Blocktypen, insgesamt <strong>105</strong>. <a href="./blocks">Alle Blocks mit echten Editorbildern</a>. Die beiden Textbilder der Vorlage zeigen dieselbe Kategorie und werden einmal berücksichtigt. Es entstehen eigene HA-YAML-/Jinja-Ausgaben; ioBroker-JavaScript wird nicht ausgeführt.</p><h2 id="abgleich-mit-den-originalen" tabindex="-1">Abgleich mit den Originalen <a class="header-anchor" href="#abgleich-mit-den-originalen" aria-label="Permalink to &quot;Abgleich mit den Originalen&quot;">​</a></h2><p>Referenzen: originaler Blockly-Quellumfang für <a href="https://github.com/RaspberryPiFoundation/blockly/blob/main/packages/blockly/blocks/loops.ts" target="_blank" rel="noreferrer">Schleifen</a>, <a href="https://github.com/RaspberryPiFoundation/blockly/blob/main/packages/blockly/blocks/math.ts" target="_blank" rel="noreferrer">Mathematik</a>, <a href="https://github.com/RaspberryPiFoundation/blockly/blob/main/packages/blockly/blocks/text.ts" target="_blank" rel="noreferrer">Text</a> und <a href="https://github.com/RaspberryPiFoundation/blockly/blob/main/packages/blockly/blocks/lists.ts" target="_blank" rel="noreferrer">Listen</a>. Die ioBroker-Ergänzungen für <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/blockly-plugins/blocks/blocks_number.ts" target="_blank" rel="noreferrer">Nachkommastellen</a> und <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/blockly-plugins/blocks/blocks_text.ts" target="_blank" rel="noreferrer">Text</a> wurden ebenfalls geprüft. Grundlage der Zielausgabe sind die <a href="https://www.home-assistant.io/template-functions/" target="_blank" rel="noreferrer">HA-Templatefunktionen</a> und <a href="https://www.home-assistant.io/docs/scripts/" target="_blank" rel="noreferrer">HA-Scriptaktionen</a>.</p><table tabindex="0"><thead><tr><th>Bereich / Original</th><th>UGSo-Umsetzung</th><th>Unterschiede / offene Varianten</th></tr></thead><tbody><tr><td>Wiederholen, solange/bis</td><td>Vorhandene native HA-repeat-Blocks</td><td>Solange prüft vorher, bis nachher.</td></tr><tr><td>Zählen von/bis/Schritt</td><td>Neuer Zählschleifenblock</td><td>Feste ganze Grenzen, Schrittbetrag, inklusive Ende auf dem Raster, automatisch auf-/absteigend, höchstens 10000 Werte. Dynamische oder gebrochene Grenzen bleiben offen.</td></tr><tr><td>Für jeden Wert aus Liste</td><td>Zusätzlich mit benannter Variable</td><td>Vor jedem Aktionskörper wird die Variable aus repeat.item gesetzt.</td></tr><tr><td>break / continue</td><td>Noch offen</td><td>HA Stop beendet den gesamten Lauf. Eine korrekte lokale Umsetzung braucht zusätzliches Kontrollflussmodell und Tests verschachtelter Schleifen.</td></tr><tr><td>Zahl, Variable erhöhen</td><td>Bereits vorhanden</td><td>Variablen erst initialisieren; Erhöhen verlangt Zahl.</td></tr><tr><td>Arithmetik, Einzelfunktionen, Trigonometrie, Konstanten</td><td>Neue Mathematik-Kategorie</td><td>Wurzel, Betrag, Negation, ln/log10, Potenzen; Winkel in Grad. Unendlich wird nicht angeboten.</td></tr><tr><td>Zahleneigenschaften</td><td>Gerade, ungerade, ganzzahlig, positiv, negativ, teilbar</td><td>Primzahlprüfung bleibt offen.</td></tr><tr><td>Runden / ioBroker-Nachkommastellen</td><td>Ein gemeinsamer Block, normal/auf/ab, 0–10 Stellen</td><td>HA/Jinja-Rundung statt JavaScript Math.round.</td></tr><tr><td>Mathematik über Liste</td><td>Summe, min/max, Mittelwert, Median, Zufallseintrag</td><td>Blockly-Modalwert als Liste aller häufigsten Werte und Standardabweichung bleiben offen; HA statistical_mode allein wäre nicht dieselbe Funktion.</td></tr><tr><td>Modulo, Begrenzen, Zufall</td><td>Neue Wertblocks</td><td>Modulo bei negativen Zahlen folgt Jinja. Ganzzahliger Zufall hat inklusive Grenzen; maximal 10000 Möglichkeiten. Zufallsbruch hat Raster 0,00001.</td></tr><tr><td>atan2</td><td>Zusätzlich aus Original-Blockly übernommen</td><td>In den gelieferten Mathematikbildern nicht sichtbar; nicht als ioBroker-Defizit gewertet.</td></tr><tr><td>Ein-/mehrzeiliger Text</td><td>Vorhandener Textblock</td><td>Originales Multiline-Feld.</td></tr><tr><td>Zeilenumbruch, Zusammenfügen, Anhängen</td><td>Neue Textblocks</td><td>LF/CRLF/CR; Zusammenfügen mit Zahnrad/+−; Anhängen weist eine neue Textvariable zu.</td></tr><tr><td>Textlänge/leer/enthält/suchen/Zeichen/Teiltext</td><td>Neue Textblocks</td><td>Indizes ab 1, Suchergebnis 0 bei nicht gefunden. Bereichsgrenzen von Anfang einschließlich Ende; Teiltext vom Ende bleibt offen.</td></tr><tr><td>Groß-/Klein-/Titelbuchstaben, trim, zählen, ersetzen, umkehren</td><td>Neue Textblocks</td><td>Literal statt Regex; Unicode-/Python-Regeln. Textumkehr ist zusätzlich im originalen Blockly-Umfang.</td></tr><tr><td>print / prompt</td><td>Log-Aktion vorhanden; prompt offen</td><td>Ein Dialog im Browser wäre kein Eingabedialog für die später ausgeführte HA-Automation.</td></tr><tr><td>Leere Liste / Liste mit Einträgen</td><td>Vorhandener Listenblock mit 0–100 Eingängen</td><td>Zahnrad/+− verändert Einträge.</td></tr><tr><td>Liste wiederholen, Länge/leer, Index, lesen, Teilliste</td><td>Vorhandene und neue Listenblocks</td><td>Lesen vom Anfang/Ende/erstes/letztes/zufällig. Teilliste einschließlich Ende vom Anfang.</td></tr><tr><td>Liste ändern / einfügen / entfernen</td><td>Neue Aktionsblocks</td><td>Neue Liste in ausgewählter Variable; keine Mutation anderer Variablen. Lesen-und-Entfernen als kombinierter Wertblock, Änderung vom Ende und zufälliges Entfernen bleiben offen.</td></tr><tr><td>Split/join, sortieren, umkehren</td><td>Neue Listenblocks</td><td>Numerisch/Text/Text ohne Groß-/Kleinschreibung; Original bleibt erhalten.</td></tr></tbody></table><h2 id="bedienung-und-laufzeitwerte" tabindex="-1">Bedienung und Laufzeitwerte <a class="header-anchor" href="#bedienung-und-laufzeitwerte" aria-label="Permalink to &quot;Bedienung und Laufzeitwerte&quot;">​</a></h2><p>Menü, heller Flyout und farbige Blocks bleiben klar getrennt; <strong>Suchen steht ganz am Ende</strong>. Mathematik ist blauviolett, Text dunkelgrün, Listen violett und Schleifen grün. Werte lassen sich in Variablen, Vergleiche, Templates und Laufzeitpausen stecken. Feste numerische Trigger-Grenzen akzeptieren weiterhin nur Zahlenblöcke, keine berechneten Templates.</p><p>Textverknüpfung besitzt 0–100 Eingänge. Variable erstellen bleibt in der Variablen-Kategorie; Text- und Listenänderungen wählen diese Variable aus. Vor Anhängen/Ändern muss sie den passenden Typ enthalten. Eine aus HA gelesene Zustandszeichenfolge bei Bedarf ausdrücklich mit dem Konvertierungsblock in eine Zahl wandeln. Ungültige Typen oder Indizes mit Nachkommastellen erzeugen Templatefehler statt stiller Konvertierung.</p><p>Index <strong>1</strong> bezeichnet das erste Element. Vom Ende zählt 1 das letzte. Beim Lesen liefert ein Index außerhalb des Bereichs leeren Text beziehungsweise null; bei Listenänderungen bleibt die Liste unverändert. Einfügen an Länge+1 hängt an. Bei Teilbereichen ergibt Start größer als Ende oder Start kleiner als 1 einen leeren Wert. Eine Endgrenze jenseits der Länge wird abgeschnitten.</p><p>Beispiel: Zähle <code>i</code> von 1 bis 5 in Schritten von 2, protokolliere im Körper einen Template-Wert mit <code>i</code>:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">repeat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      for_each</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{{ range(1, 6, 2) | list }}&#39;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      sequence</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">variables</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{{ repeat.item }}&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">action</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">system_log.write</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">info</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">            message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{{ i }}&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>Das ergibt 1, 3, 5. Verschachtelte Schleifen sollten unterschiedliche Variablennamen verwenden; repeat.item bezeichnet jeweils den innersten Durchlauf. Wiederholte Zufalls-/zeitabhängige Ausdrücke zuerst in eine Variable speichern, wenn derselbe Wert an mehreren Stellen gebraucht wird: verschachtelte Templates können Eingänge mehrfach auswerten.</p><h2 id="unterschiede-zu-javascript-und-speicherung" tabindex="-1">Unterschiede zu JavaScript und Speicherung <a class="header-anchor" href="#unterschiede-zu-javascript-und-speicherung" aria-label="Permalink to &quot;Unterschiede zu JavaScript und Speicherung&quot;">​</a></h2><ul><li>Bei 0 Nachkommastellen wird 2,5 zu 2 und 3,5 zu 4; JavaScript Math.round verhält sich anders. Auf-/Abrunden verwendet ceil/floor.</li><li>Negatives Modulo: −9 modulo 2 ergibt 1. Winkel werden zwischen Grad und HA-Radiant umgerechnet.</li><li>Textoperationen verwenden Unicode-Codepunkte. Ein Emoji kann in JavaScript zwei UTF-16-Einheiten haben; kombinierte Zeichen/Grapheme sind weiterhin mehrere Codepunkte. Titelbuchstaben und trim folgen Python/Jinja.</li><li>Leerer Suchtext wird bei Zählen/Ersetzen ausdrücklich als 0/unveränderter Text behandelt. Treffer überlappen nicht. Suche ist wörtlich und unterscheidet Groß-/Kleinschreibung.</li><li>Leere Liste: Summe 0, andere Mathematik-Aggregate und Zufallseintrag null. Numerische Aggregation/Sortierung verlangt echte Zahlen, keine Boolean- oder Textwerte. Python-Gleichheit kann beim Suchen 1 und wahr als gleich behandeln und unterscheidet sich von JavaScript-Referenzgleichheit.</li><li>Listenänderungen erzeugen Kopien durch Slices und neue HA-Variablenzuweisung. Keine list.append-/pop-Mutation in der unveränderlichen HA-Sandbox.</li></ul><p>Projekt-JSON behält Blockformen, Felder, Dropdowns, Reihenfolge und verknüpfte Einträge. YAML-Import erhält die Bedeutung, öffnet komplexe Wertausdrücke als allgemeine Templates und Zählschleifen als native Für-jeden-Schleife mit Variablenzuweisung. YAML enthält keine Informationen, aus denen sich die ursprünglichen Blockly-Formen eindeutig rekonstruieren lassen.</p><p>Geprüft: alle 37 neuen Blocktypen durch JSON/YAML, Grenzfälle, unveränderliche Jinja-Sandbox mit HA-Mathematik-Helfern, Kategorien und Text-Plus-Button im Browser, App-/Dokumentationsbuild und Docker-Vorschau. Die Ausführung in einer echten Home-Assistant-Instanz steht noch aus.</p>`,16)])])}const p=n(r,[["render",s]]);export{g as __pageData,p as default};
